const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon for Jakarta Bay.
  // This polygon roughly covers the coastal area of Jakarta facing the bay.
  const jakartaBay = ee.Geometry.Polygon(
    [[[106.69, -6.0],
      [106.94, -6.0],
      [106.94, -6.2],
      [106.69, -6.2],
      [106.69, -6.0]]]
  );

  const year = '2018'; // Closest available GHSL Built-Up year to 2021.

  // 2. Data Acquisition
  // Use the Global Human Settlement Layer (GHSL) built-up surface grid.
  // This dataset provides built-up presence (1) or absence (0).
  const ghslImageId = 'JRC/GHSL/P2023_GHS_BUILT_S/' + year;
  let ghslBuilt = null;
  try {
    ghslBuilt = ee.Image(ghslImageId).select('built_s');
  } catch (e) {
    console.log("Error loading GHSL image: " + e.message);
    console.log("C3"); // Calculation failure, possibly due to incorrect image ID or permissions
    return;
  }

  // Check if the image exists and has the expected band.
  if (!ghslBuilt) {
    console.log(`C1`); // Image failed to load, effectively an empty collection for a single image.
    return;
  }

  // Clip the image to the area of interest (Jakarta Bay)
  ghslBuilt = ghslBuilt.clip(jakartaBay);

  // 3. Processing
  // Mask non-built-up areas. We are interested only in pixels where 'built_s' is 1.
  const builtUp = ghslBuilt.updateMask(ghslBuilt.eq(1));

  // Get the projection of the image to determine pixel area.
  // GHSL has a nominal scale of approximately 30 meters.
  const pixelScale = ghslBuilt.projection().nominalScale(); // Should be around 30 meters

  // Calculate the area of each pixel in square meters.
  // Ensure the scale is in meters for accurate area calculation.
  const pixelAreaSqM = ee.Number(pixelScale).multiply(ee.Number(pixelScale));

  // Count the number of built-up pixels within the Jakarta Bay region.
  // Use a fine scale for accuracy but not so fine to cause memory issues.
  // The GHSL product is ~30m, so using 30m or 100m scale for reduction is appropriate.
  const countBuiltPixels = builtUp.reduceRegion({
    reducer: ee.Reducer.sum(), // Summing '1's counts pixels
    geometry: jakartaBay,
    scale: 30, // Use the native resolution for accuracy
    maxPixels: 1e9
  });

  let totalBuiltPixels = null;
  try {
    totalBuiltPixels = await ee.data.computePromise(countBuiltPixels.get('built_s'));
  } catch (e) {
    console.log("Error computing pixel count: " + e.message);
    console.log("C3");
    return;
  }

  // Check for C2 (No Valid Pixels)
  if (totalBuiltPixels === null || totalBuiltPixels === 0) {
    console.log(`No valid built-up pixels found in ${year} for Jakarta Bay.`);
    console.log("C2");
    return;
  }

  // 4. Calculation
  // Calculate total built-up area in square meters.
  const totalAreaSqM = ee.Number(totalBuiltPixels).multiply(pixelAreaSqM);

  // Convert square meters to hectares (1 hectare = 10,000 square meters).
  const totalAreaHectares = totalAreaSqM.divide(10000);

  // Get the final result.
  let finalAreaHectares = null;
  try {
    finalAreaHectares = await ee.data.computePromise(totalAreaHectares);
  } catch (e) {
    console.log("Error computing final area: " + e.message);
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  const thresholdHectares = 800;

  console.log(`Analyzed area (Jakarta Bay) for year: ${year}`);
  console.log(`Total built-up pixels found: ${totalBuiltPixels.toFixed(0)}`);
  console.log(`Calculated artificial land area: ${finalAreaHectares.toFixed(2)} hectares`);

  if (finalAreaHectares === null || isNaN(finalAreaHectares)) {
    console.log("C3"); // Calculation resulted in null or NaN
  } else if (finalAreaHectares > thresholdHectares) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
